insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, seasons, times, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('vanor', 'Vanor', 'EDP', 'unisex', 'gurmaniski', 'Tabakas, vanilė ir kakava', 'Sodrus, šiltas ir prabangus kvapas. Tabako lapai ir prieskoniai atsiveria į kreminę vanilę, kakavą ir tonkos pupeles, o džiovinti vaisiai ir mediena palieka ilgą, jaukų pėdsaką. Kvapas šaltiems vakarams ir ypatingoms progoms.', '{"top":["Tabako lapai","Imbieras","Prieskoniai"],"heart":["Vanilė","Kakava","Tonkos pupelės","Tabako žiedai"],"base":["Džiovinti vaisiai","Mediena"]}'::jsonb, 5, 4, array['ruduo','žiema']::text[], array['vakaras']::text[], '[{"ml":33,"price":29.9},{"ml":100,"price":59.9}]'::jsonb, 3.9, '{"liquid":"#8A5A2B","tint":"#F3E7DA","cap":"gold","shape":"rect"}'::jsonb, null, 1, '2026-09-01', null, array['img/kvapai/vanor-1.webp']::text[], 'Tom Ford – Tobacco Vanille') on conflict (id) do nothing;
