insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, seasons, times, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('bellara', 'Bellara', 'EDP', 'moterims', 'gurmaniski', 'Irisas, pralinė ir vanilė', 'Saldus, švytintis kvapas. Juodieji serbentai ir kriaušė atsiveria į irisą, jazminą ir apelsino žiedus, o pralinė, vanilė, pačiulis ir tonkos pupelės sukuria minkštą, jaukų ir ilgai išliekantį pėdsaką. Kvapas džiaugsmui kasdien.', '{"top":["Juodieji serbentai","Kriaušė"],"heart":["Irisas","Jazminas","Apelsino žiedai"],"base":["Pralinė","Vanilė","Pačiulis","Tonkos pupelės"]}'::jsonb, 5, 4, array['pavasaris','ruduo','žiema']::text[], array['diena','vakaras']::text[], '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#D98BA0","tint":"#F8E9EC","cap":"gold","shape":"rect"}'::jsonb, null, 5, '2026-09-15', null, array['img/kvapai/bellara-1.webp']::text[], 'Lancôme – La Vie Est Belle') on conflict (id) do nothing;
