insert into public.settings (id, data) values (1, '{"shop":"Vaidore","domain":"vaidore.com","tagline":"Prabangių kvapų įkvėpti Vaidore kvepalai. Pirma išbandykite 2 ml mėginuką.","currency":"eur","freeShippingFrom":60,"maxQty":10,"dispatch":"1–2 d. d.","returnDays":14,"hero":{"product":"vanor","eyebrow":"Žiemos kolekcija","title":"Vanor","text":"Tabakas, vanilė ir kakava – šilčiausias sezono kvapas."},"countries":["LT","LV","EE"],"shipping":[{"id":"omniva","name":"Omniva paštomatas","price":2.99,"days":"1–2 d. d."},{"id":"dpd","name":"DPD kurjeris iki durų","price":4.99,"days":"1–2 d. d."}],"company":{"name":"[Įmonės pavadinimas]","code":"[Įmonės kodas]","vat":"[PVM mokėtojo kodas]","address":"[Buveinės adresas]","email":"info@vaidore.com","phone":"[Telefonas]"},"story":{"title":"Mūsų istorija","text":"Vaidore gimė iš paprastos minties: kvapą reikia pažinti prieš jį perkant. Todėl kiekvieną kvapą siūlome ir 2 ml mėginuku, o natas aprašome taip, kad suprastumėte be parfumerio žodyno.","image":""},"discovery":{"id":"atradimu-rinkinys","name":"Atradimų rinkinys","count":5,"price":14.9,"text":"Bet kurie 5 kvapai po 2 ml – išbandykite namuose, ramiai."},"sampleCredit":{"days":30,"minOrder":39},"gift":{"price":2.5,"noteMax":200},"notifyForm":"","analytics":{"plausible":"","vercel":false},"inspired":{"show":true,"note":"Prekių ženklai priklauso jų savininkams. Vaidore su jais nesusijusi – pavadinimas nurodo tik kvapo kryptį."}}'::jsonb) on conflict (id) do nothing;
